-- ApexLib Example

local ApexLib = loadstring(game:HttpGet(
    "https://raw.githubusercontent.com/Teapokk/ApexLib/refs/heads/main/ApexLib.lua"
))()

local Window = ApexLib:CreateWindow({
    Title = "ApexLib Example",
    Name = "Example"
})

local Main = Window:AddTab("Main")

Main:AddButton({
    Title = "Hello",
    Callback = function()
        print("Hello from ApexLib!")
    end
})
